INSERT INTO campus_faqs (id, category, question, keywords, where_text, duration_text, steps_text, tip, sort_order) VALUES
(1,'食品健康','食堂几点开饭','食堂 几点 开饭 供餐时间 早餐 午餐 晚餐 窗口 营业','食堂一层早餐7:00-9:00、午餐11:00-13:30、晚餐17:00-19:30；二层风味窗口10:30-20:00连供，周末各时段顺延30分钟。','赶不上正餐可去二层风味窗口；遇节假日或考试周，供餐时段会临时调整，以门口当日公告为准。','先看当日公告~食堂门口电子屏列出各窗口供餐时段与临时调整~留意周末顺延 30 分钟的通知~出门前 1 分钟;;错峰取餐~11:30-12:00、17:30-18:00 排队最长，提前或延后 20 分钟到~校园卡（模拟）~省约 10 分钟','示例：同学A 改到 11:10 取餐，排队从 12 分钟降到 3 分钟。',1),
(2,'食品健康','食堂哪个窗口有低脂餐','低脂餐 哪个窗口 轻食 蒸煮 热量 少油 减脂 低卡','一层6号「轻食窗口」和二层「蒸煮窗口」供低脂餐：每份标注热量与蛋白质，单份控制在350-450千卡，招牌是鸡胸藜麦碗、清蒸鱼套餐、白灼时蔬。','低脂餐每日限量，通常 13:00 前售完；想少油可备注「少油少盐」，出餐约多等 3 分钟。','认准标识~窗口上方绿色「低脂」牌，菜单带每份热量与蛋白质克数~看清是「每份」还是「每 100 克」~点餐前 10 秒;;搭配建议~一份低脂主菜配半份米饭和一份清汤，蛋白质约 25-30 克~别再加炸物或含糖饮料~一餐约 15 分钟','示例：同学D 常选白灼时蔬配清蒸鱼，单餐约 420 千卡。',2),
(3,'食品健康','食堂菜品的热量怎么查','热量 怎么查 卡路里 营养成分 菜品 营养卡 二维码','在对话里问「食堂三楼有什么低脂的」可看菜名、热量和蛋白质；也可扫窗口立牌的模拟二维码，或看打餐台纸质营养卡上每份的标注数值。','数据每周随菜单更新一次；同一道菜大份约比小份多 120-180 千卡，按实际分量折算更准。','对话查~输入「今天吃了多少卡路里」看当日三餐明细与总热量~先在顶部切到自己的身份~即时;;现场查~打餐台营养卡按每份标注，窗口立牌二维码（模拟）指向同一份数据~注意「每份」与「每 100 克」的区别~约 30 秒','示例：同学B 把大份菜按 1.5 份折算，当日总热量更接近真实值。',3),
(4,'作息健康','宿舍几点熄灯','宿舍 熄灯 几点 断网 门禁 作息 关灯 时间','模拟宿舍楼周日至周四23:00熄灯断网，周五、周六与节假日前夜延至23:30；走廊和卫生间不断电，考试周可申请延时自习。','熄灯后可用自带台灯；连续三天以上睡眠不足 6 小时，建议问一句「我这周睡眠质量如何」看看曲线。','对齐作息~把需要亮灯的收尾事项放到 22:30 前做完~手机设 22:45 提醒，留出 15 分钟洗漱~约两周养成;;延时自习~考试周向本楼宿管值班室（模拟）登记，使用公共自习区~写明日期时段，以不打扰舍友为前提~登记 2 分钟','示例：同学A 固定 23:00 前入睡，近 7 天平均睡眠 7 小时 40 分。',4),
(5,'作息健康','熬夜对身体有什么影响','熬夜 影响 危害 睡眠不足 生物钟 免疫力 注意力 记忆力','连续熬夜会打乱生物钟：第二天注意力、记忆力下降、白天嗜睡；长期还会让免疫力变差、食欲和血糖波动更明显，靠周末补觉很难补回来。','若持续两周入睡困难、白天明显乏力或情绪低落，建议预约校医或到心理健康中心（模拟）聊聊。','先看数据~问「我这周睡眠质量如何」，对照 7 天入睡时间与时长~重点看是否连续 3 天少于 6 小时~即时;;做两个调整~固定起床时间，睡前一小时调暗屏幕、停止高强度用脑~下午 3 点后少喝咖啡浓茶~坚持 7 天再看曲线','示例：同学B 近 7 天平均只睡 6 小时 05 分，白天困倦评分明显偏高。',5),
(6,'作息健康','怎么改善睡眠质量','改善睡眠 睡眠质量 失眠 入睡 作息 助眠 怎么睡 办法','先固定起床时间再倒推7-8小时上床；睡前一小时离开强光屏幕、不做剧烈运动，晚餐别太撑，下午三点后不喝咖啡浓茶，白天晒20分钟太阳。','连续记录 7 天再看变化；躺床 20 分钟仍睡不着就起身做点安静的事，困了再回床。','固定节律~周末起床时间也别比平日晚超过 1 小时~用「我这周睡眠质量如何」核对曲线~约 7 天见效;;睡前减法~22:30 起调暗灯光、放下手机，改看纸质书或做 5 分钟腹式呼吸~避免靠酒精助眠~每晚约 30 分钟','示例：同学A 把起床时间固定在 7:00，一周后质量评分从 78 升到 88。',6),
(7,'运动健康','体育馆开放时间','体育馆 开放时间 几点 闭馆 约场 健身房 器材 营业','模拟体育馆工作日6:30-22:00、周末8:00-21:00开放；羽毛球场和健身房需提前在小程序（模拟）约场，器材凭校园卡在服务台借，闭馆前30分钟停止入场。','想知道此刻挤不挤，问「体育馆现在人多吗」会返回在场人数、空闲器材与预计空闲时段。','先约场~小程序（模拟）→ 场馆预约，选项目与时段~18:00-20:00 热门，建议提前 1 天约~约 1 分钟;;错峰去~7:00-8:00 或 14:00-16:00 器材更空~校园卡（模拟）、运动鞋~省排队约 15 分钟','示例：同学C 改到早上 7 点训练，跑步机不用等。',7),
(8,'运动健康','跑步前要热身多久','热身 跑步 多久 拉伸 动态拉伸 运动前 准备活动 时间','热身8-12分钟：先5分钟快走或慢跑把心率提起来，再做3-5分钟动态拉伸，活动踝、膝、髋和肩；天冷或要冲刺时延长到15分钟，别一上来就静态压腿。','热身到身体微微发热、呼吸略加快即可开跑；出现关节刺痛应停下，别硬撑。','升温~快走渐到慢跑 5 分钟，配速以能完整说话为准~穿合脚跑鞋，选平整路面~5 分钟;;动态拉伸~高抬腿、弓步走、踝绕环各 2 组，每组 10 次~幅度由小到大，不做弹震式压腿~3-5 分钟','示例：同学C 每次先做 10 分钟热身，跑后膝痛次数明显减少。',8),
(9,'运动健康','运动后肌肉酸痛怎么办','肌肉酸痛 运动后 延迟性酸痛 拉伸 恢复 缓解 怎么办','延迟性酸痛常在运动后12-24小时出现，2-3天自行缓解：当天做10分钟低强度走动与温和拉伸，分次补水，保证蛋白质和睡眠，48小时内别重复练同一肌群。','若出现尖锐刺痛、关节肿胀、单侧明显肿痛或尿液颜色变深，别自行处理，尽快预约校医。','轻量活动~散步或慢骑 10 分钟促进循环，随后静态拉伸大腿与小腿~以轻微牵拉感为限，不追求疼~10-15 分钟;;恢复补给~运动后 2 小时内补一份蛋白质，全天分次喝水~别一次猛灌大量白水~当天','示例：同学B 酸痛当天继续大重量深蹲，第二天疼到影响走路。',9),
(10,'校医就诊','校医室在哪里','校医室 在哪里 位置 怎么走 医务室 地址 急诊 路线','模拟校区校医室在3号学生宿舍楼一层西侧，从宿舍区主入口步行约3分钟；门口有绿色十字标识和当日值班牌，夜间急诊铃在侧门，按铃后值班人员来接。','不确定路线可说「我要预约校医」，预约成功页会再列一次位置；夜间急症先按侧门铃。','白天就诊~从宿舍区主入口直走，见绿色十字标识右转即到~校园卡（模拟）、既往用药记录~步行约 3 分钟;;夜间到诊~走侧门按急诊铃，不要在主门口等候~说清症状与所在楼栋~值班响应约 5 分钟','示例：同学A 第一次走错到行政楼，按绿色十字标识找最快。',10),
(11,'校医就诊','校医室几点上班','校医室 几点 上班 门诊时间 值班 急诊 节假日 开放','模拟校医室工作日8:00-12:00、14:00-20:00门诊，周末9:00-17:00；12:00-14:00只接急症，20:00后改走侧门急诊铃。','节假日安排看门口值班牌；想少等可先预约时段，发热或急性腹痛不必等门诊时间，直接走急症通道。','选时段~预约页可选上午、下午、晚间，晚间号源较少~提前 10 分钟到，带校园卡（模拟）~候诊约 10-20 分钟;;非门诊时间~中午与夜间走侧门急诊铃，说明症状紧急程度~不要自行服用处方药~即时响应','示例：同学D 约了下午 15:00 时段，到现场 8 分钟就看上。',11),
(12,'校医就诊','看校医要带什么','看校医 带什么 材料 校园卡 药盒 体温 就诊准备 需要','带校园卡（模拟）和正在吃的药盒或清晰照片即可；有发热先在前台量体温并记下最高值与时间，把症状从哪天开始、有没有加重写清楚，能帮值班校医更快判断。','此前做过的检查报告（模拟）可一并带上；没有也不影响初诊，别为此推迟就诊。','必带~校园卡（模拟）用于登记，药盒或照片用于核对成分~别只报商品名，成分名更重要~出门前 1 分钟;;写清三件事~症状起始时间、体温最高值、是否自行用药及效果~先在备忘录按时间顺序列好~约 3 分钟','示例：同学B 带上退烧药盒，值班校医一眼看出两种药成分重复。',12),
(13,'心理健康','学校有心理咨询吗','心理咨询 有吗 心理中心 预约 谈话 压力 情绪 在哪','有。模拟校区心理健康中心在活动中心二层，工作日9:00-17:00可约一对一谈话，每次50分钟；也可先在前台登记，或先从睡眠、压力相关问答看起。','谈话内容按模拟设定仅本人与咨询员可见；连续两周情绪低落、失眠或影响上课，建议尽快预约。','预约~活动中心二层前台登记，或用校内小程序（模拟）选时段~只写想聊的主题即可，不必先准备完整叙述~登记 3 分钟;;首次谈话~50 分钟，主要把困扰和近期作息说清楚~可带自己记的睡眠记录~一次 50 分钟','示例：同学B 因连续熬夜情绪波动，约过一次谈话后调整了作息。',13),
(14,'心理健康','压力大睡不着怎么办','压力大 睡不着 失眠 焦虑 放松 呼吸 怎么办 入睡','睡前1小时把次日待办写下来，把念头外置；再做5分钟缓慢腹式呼吸。躺20分钟没睡着就起身到弱光处看纸质书，困了再回床，别盯着时钟算时间。','连续两周以上入睡困难、白天明显影响上课，建议预约心理咨询或校医，别自行吃助眠药。','卸载念头~用纸写下明天要做的 3 件事，写完合上本子~别在床上刷手机「放松」~睡前 5 分钟;;呼吸放松~吸气 4 秒、呼气 6 秒，重复 20 轮，注意力放在呼气~呼气比吸气长才有效~约 5 分钟','示例：同学B 用待办清单后，入睡时间从 01:40 提前到 00:20。',14),
(15,'心理健康','心理咨询要收费吗','心理咨询 收费 免费 多少钱 次数 费用 价格 凭证','模拟校区内一对一心理咨询对本校学生免费，每学期可约8次，超出后可转团体辅导或由中心协助转介；校内服务不收费用，也不需要提供任何缴费凭证。','如需校外专科评估（模拟），是否产生费用以本人自愿选择为准，中心不代办收费。','校内预约~活动中心二层前台登记，出示校园卡（模拟）即可~不用带缴费或审批材料~约 3 分钟;;次数查询~在预约记录里看本学期已用次数~临近 8 次可与咨询员商量后续安排~即时','示例：同学A 本学期约过 3 次，剩余次数在预约记录里可查。',15),
(16,'常见病症','感冒了怎么办','感冒 怎么办 鼻塞 咽痛 发烧 休息 抗生素 处理','普通感冒多由病毒引起，以休息和对症为主：分次喝温水、保证睡眠，鼻塞用生理盐水喷鼻，咽痛用淡盐水漱口；一般5-7天好转，不必急着吃抗生素。','若高热超过 3 天、呼吸困难、胸痛，或第 7 天症状反而加重，别硬扛，预约校医面诊。','居家照护~减少熬夜与剧烈运动，饮食清淡、分次补水~居室定时通风，别捂汗~前 3 天最关键;;对症处理~鼻塞用生理盐水喷鼻，发热不适按说明书用一种退热药~不叠加多种复方感冒药~按说明书间隔','示例：同学C 同时吃两种复方感冒药，出现明显心慌后到校医室咨询。',16),
(17,'常见病症','发烧多少度要去医院','发烧 多少度 体温 38.5 高热 去医院 校医 急诊 测量','腋温超过38.5℃且明显不适，或发热持续3天以上，建议预约校医；若达39℃以上、意识模糊、呼吸困难或出现皮疹，直接走急症通道，别自行加药。','量体温前静坐 15 分钟、擦干腋下，记下数值与测量时间，就诊时一并告诉校医。','先规范测量~静坐 15 分钟后测腋温 5 分钟，记下数值和时间~运动后、喝热水后别立刻测~约 20 分钟;;分档处理~38.5℃ 以下先休息补水观察；以上或超 3 天预约校医~退热药按说明书间隔，不叠加~当天判断','示例：同学D 记录了 3 次体温曲线，校医初诊时省去重复问诊。',17),
(18,'常见病症','拉肚子能吃什么','拉肚子 腹泻 吃什么 饮食 补液 忌口 能吃什么 恢复','急性腹泻先补液再进食：少量多次喝温水或口服补液盐，缓解后从米粥、面条、蒸苹果、香蕉等低脂易消化食物开始，2-3天内避开油炸、生冷、奶茶和酒精。','若一天超过 6 次、带血或黏液、持续 2 天不缓解，或伴高热与明显口干，尽快预约校医。','先补液~每次 100-200 毫升，隔 10 分钟一次，别一次猛灌~口服补液盐按说明配比，不要自行加浓~前 4-6 小时;;逐步复食~米粥→面条→软饭，每餐七分饱~暂避奶制品、粗纤维与辛辣~2-3 天','示例：同学B 腹泻当天喝冰奶茶，症状又反复了一天。',18),
(19,'用药常识','感冒药能混着吃吗','感冒药 混着吃 一起吃 重复用药 对乙酰氨基酚 成分 搭配','不建议。很多复方感冒药都含对乙酰氨基酚，两种一起吃容易重复用药、伤肝；换药前先看药盒成分表，同一成分只留一种，间隔严格按说明书，别自行加量。','已在吃慢性病药，或服药后出现皮疹、心慌、恶心，先停药并把药盒带去校医室确认。','核对成分~把两盒药的「成分」栏并排看，重点找对乙酰氨基酚、伪麻黄碱~商品名不同也可能是同一成分~1 分钟;;只留一种~按一种药的说明书间隔服用，记录每次时间~不因「没好转」就叠加第二种~按说明书','示例：同学C 叠吃两种复方感冒药后心慌，带药盒到校医室核对成分。',19),
(20,'用药常识','抗生素要吃完整疗程吗','抗生素 疗程 停药 漏服 细菌感染 吃完 剩药 医嘱','要按校医开的疗程和间隔吃完，别因为退烧就自行停药，也别把剩下的药留着下次吃；漏服按说明书补，接近下次服药时间就跳过，不要一次吃双倍补回来。','抗生素只对细菌感染有效，普通感冒不需要；是否使用、用多久由校医判断，出现皮疹或腹泻及时复诊。','按时按量~设手机提醒固定间隔，餐前餐后要求看说明书~记录开始日期与总天数~全程按医嘱;;不自行调整~症状好转也吃满疗程；剩下的药不留存、不转给同学~漏服别加倍补~就诊时问清','示例：同学A 退烧后自行停药，两天后症状反复又复诊一次。',20),
(21,'用药常识','空腹能吃药吗','空腹 吃药 饭前 饭后 说明书 胃 服药时间 能吗','看药盒或说明书的「用法用量」：标注餐前或空腹服的按空腹吃，标注餐后或随餐服的先吃点东西；没写又注明胃肠道反应的通常饭后更稳妥，别一律空腹吞。','布洛芬等非甾体抗炎药建议随餐或餐后；服药后胃痛、反酸明显，带药盒预约校医确认。','先读说明~找「空腹 / 餐前 / 餐后 / 随餐」字样，再看禁忌栏~别凭药名猜，同成分不同剂型要求不同~30 秒;;拿不准就问~预约校医时把药盒拍照或实物带上~说明自己平时胃是否敏感~就诊时','示例：同学D 空腹吃布洛芬后胃痛，改为餐后服明显缓解。',21),
(22,'体检体测','体测有哪些项目','体测 项目 有哪些 肺活量 50米 800米 1000米 内容 缓测','模拟校区年度体测共6项：身高体重、肺活量、50米跑、坐位体前屈、立定跳远、男1000米/女800米；另含视力与血压筛查，3个工作日后可查成绩。','有心脏病、近期骨折或急性发热可申请缓测，先到校医室（模拟）评估再交体育教研室。','确认批次~按学院通知时段到场，先测静态项目再测耐力跑~校园卡（模拟）、运动服~全程约 40 分钟;;缓测申请~身体不适先到校医室（模拟）评估~说明具体症状，别硬跑~约 1 个工作日','示例：同学C 感冒发热当周申请缓测，两周后补测完成。',22),
(23,'体检体测','体测前要注意什么','体测前 注意 准备 热身 饮食 睡眠 别空腹 缓测 事项','前一周别突然加练，前一天保证7小时睡眠、不饮酒；测试当天提前1小时吃易消化的碳水餐，到场先做10分钟动态热身，长跑前别猛灌水，也别空腹硬跑。','有胸闷、头晕、关节痛或正在发热，当天先别测，到校医室评估后申请缓测。','前一天~睡够 7 小时，避免熬夜与高强度力量训练~备好运动鞋、水、毛巾~前一晚;;当天~提前 1 小时吃七分饱的碳水餐，热身 10 分钟再上场~长跑后少量多次补水~提前 60 分钟到场','示例：同学B 熬夜后空腹跑 1000 米，中途头晕被扶到休息区。',23),
(24,'体检体测','体检报告在哪里看','体检报告 在哪里看 查询 健康档案 报告 上传 异常项','体检报告在模拟校内健康门户→我的档案→体检报告查看，入学体检一般5个工作日内上传；也可在对话里问「我的健康数据谁能看到」先弄清授权范围。','报告里的异常项别自行下结论，带报告预约校医解读；报告仅本人和经授权的校医可见。','查报告~健康门户（模拟）→ 我的档案 → 体检报告，按年度筛选~用校园卡（模拟）账号登录~约 2 分钟;;看异常项~把标红项目记下，预约校医时一并带上~别照着网上结论自行用药~就诊时','示例：同学A 把标红的血红蛋白项带给校医，确认后只是近期饮食偏少。',24),
(25,'急救常识','有人晕倒了怎么办','晕倒 昏倒 急救 心肺复苏 按压 AED 怎么办 无反应','先确认环境安全并轻拍呼唤；无反应、无正常呼吸时立刻让人按急症铃取AED，自己开始胸外按压（两乳头连线中点、每分钟100-120次、深约5厘米），别搬动、别喂水。','AED 到场后按语音提示贴片并继续按压；恢复呼吸后侧卧保暖，等专业人员接手，别自行判断「没事了」。','判断与呼救~拍肩呼唤 5-10 秒，同时指定一人按急症铃、一人取 AED~说清所在楼栋与楼层~10 秒内;;持续按压~双臂垂直、掌根置于胸骨中下段，不间断按压~有人接替前不要停，别掐人中代替按压~到专业人员接手','示例：模拟演练中同学A 负责呼救、同学C 负责按压，分工比围观更快。',25),
(26,'急救常识','烫伤了怎么处理','烫伤 烧伤 冷水冲 水泡 牙膏 处理 急救 怎么办','立刻用流动冷水冲15-20分钟降温，边冲边轻轻去掉戒指手表等束缚物；别涂牙膏、酱油或香油，也别挑破水泡，冲完用干净纱布或保鲜膜松盖，再到校医室处理。','面积超过手掌、起大水泡、脸部或关节处烫伤，冲水后直接走急症通道，别自行抹药。','冲~流动冷水 15-20 分钟，水流别太急~不用冰水，避免二次冻伤~15-20 分钟;;盖与送~用干净纱布或保鲜膜松松覆盖创面~不涂偏方、不撕脱皮~随后就诊','示例：同学D 被热水烫到手背后先冲水 20 分钟，恢复明显更快。',26),
(27,'急救常识','东西卡喉咙了怎么办','卡喉咙 异物 噎住 海姆立克 腹部冲击 急救 怎么办','能咳能说话就鼓励用力咳，别抠喉；若说不出话、抓颈、面色发青，立刻让人按急症铃，并从背后环抱，在脐上两指向内上方快速冲击，直到异物排出或专业人员接手。','孕妇或肥胖者改为胸部冲击；患者失去意识时立即改为胸外按压，别继续盲目拍背。','先判断~问「能说话吗」，能咳就鼓励自主咳嗽~不要喂饭、喝水试图「顺下去」~数秒内;;腹部冲击~站背后环抱，一手握拳置脐上两指，另一手包住快速向内上冲击~每次单独有力，连续 5 次评估一次~持续到排出','示例：模拟演练里同学B 先呼救再冲击，比先跑去叫人更省时间。',27),
(28,'健康档案','我的健康数据谁能看到','健康数据 谁能看到 隐私 授权 权限 访问日志 可见 保密','按模拟设定，只有本人和经本人明确授权的校医能看；辅导员、任课教师、同学都看不到具体数值，食堂与体育馆只收到脱敏统计，授权记录随时可查、可撤销。','每次查看都会留下一条模拟访问日志，含查看人角色、时间与用途，本人在健康门户里可查。','看授权列表~健康门户（模拟）→ 我的档案 → 授权管理~逐条核对被授权角色与有效期~约 1 分钟;;看访问日志~同一页面切到「访问记录」~发现陌生记录立即撤销并咨询校医室~即时','示例：同学A 的档案里只有一条对校医室的有效授权。',28),
(29,'健康档案','怎么授权校医查看我的数据','授权 校医 查看 健康数据 怎么授权 开放范围 有效期','在健康门户（模拟）→我的档案→授权管理点「新增授权」，选校医室、勾选开放范围（如体检报告、近7天睡眠）并设有效期；确认后校医才能在就诊时看到对应内容。','授权默认 30 天到期自动失效；可只开放本次就诊需要的项，不必一次全开。','选角色与范围~角色选「校医室」，按需要勾选数据项~不必开放全部历史记录~约 2 分钟;;设有效期~建议设为本次就诊前后 7 天~记下授权编号，方便后续撤销~即时生效','示例：同学D 只开放体检报告 7 天，就诊结束后授权自动失效。',29),
(30,'健康档案','怎么撤销授权','撤销授权 取消授权 怎么撤销 权限 关闭 健康档案 失效','在健康门户（模拟）→我的档案→授权管理找到对应条目，点「撤销」并确认，撤销即时生效；已产生的就诊记录按规定留档，但不再对新访问开放，建议顺便看一眼访问日志。','若不记得授权过哪些，按「有效期」排序逐条核对；发现陌生授权立即撤销并到校医室核实。','找到条目~授权管理里按角色或有效期筛选~核对授权编号与开放范围~约 1 分钟;;撤销与复查~点「撤销」→ 确认 → 刷新列表确认状态变为已失效~同页查看最近访问记录~即时','示例：同学B 就诊后撤销了授权，列表状态当场变为已失效。',30)